__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"REVIEW_EVERY_DAYS",{enumerable:!0,get:function(){return t}}),Object.defineProperty(e,"DISPUTE_EMAIL",{enumerable:!0,get:function(){return n}}),Object.defineProperty(e,"DISPUTE_ISSUES_URL",{enumerable:!0,get:function(){return s}}),Object.defineProperty(e,"EXCLUDED_SOURCES",{enumerable:!0,get:function(){return o}}),Object.defineProperty(e,"CLAIMS",{enumerable:!0,get:function(){return h}}),Object.defineProperty(e,"STRENGTH_LABEL",{enumerable:!0,get:function(){return p}}),Object.defineProperty(e,"STUDIED_LABEL",{enumerable:!0,get:function(){return y}}),e.claimsFor=function(t){return h.filter(n=>n.appliesTo.includes(t))},e.claimById=function(t){return h.find(n=>n.id===t)},e.disputeMailto=function(t){const s=`[Evidence dispute] ${t.id} v${t.version}`,o=`Claim: ${t.rule}\n\nWhat's wrong or missing?\n\n\nSource you'd suggest (DOI or link):\n\n\n(Please don't include personal health details.)`;return`mailto:${n}?subject=${encodeURIComponent(s)}&body=${encodeURIComponent(o)}`},e.disputeIssueUrl=function(t){return`${s}&title=${encodeURIComponent(`[Evidence] ${t.id} v${t.version}`)}&claim=${encodeURIComponent(t.id)}`};const t=180,n='jolumobu7@gmail.com',s='https://github.com/jolumobu7/Snatched-Summer/issues/new?template=evidence-dispute.yml',o=[{cite:'Viana et al., 2019 (BJSM) "Is interval training the magic bullet for fat loss?"',url:'https://doi.org/10.1136/bjsports-2018-099928',reason:'Retracted after data-extraction errors were found. Replaced by Steele et al., 2021.'}],l=['hip_thrust','glute_bridge','back_extension','rdl','single_leg_rdl','squat','leg_press','split_squat','reverse_lunge','step_up','abduction','banded_walk','kickback','leg_curl','lunge','lat_pulldown','assisted_pullup','row','band_row','shoulder_press','incline_press','lateral_raise','face_pull','pushup','dead_bug','plank','side_plank','crunch','pallof'],u='Founder review (pending independent expert review)',c='2026-11-23',h=[{id:'progressive-overload',rule:'When you finish every set at the target, the next session adds a small amount of weight (or reps). Too hard? It backs off.',topic:'Training',strength:'consensus',caveat:'The exact step sizes (5 lb lower body, 2.5 lb upper body) are our practical choice, not numbers from the position stand.',sources:[{cite:'ACSM, 2009',title:'American College of Sports Medicine position stand. Progression models in resistance training for healthy adults',journal:'Medicine & Science in Sports & Exercise',year:2009,url:'https://pubmed.ncbi.nlm.nih.gov/19204579/',kind:'position stand',studied:'adults',finding:'Progressive overload is a core principle: training needs to get gradually harder to keep producing results, applied to each person\u2019s goals and training status.'}],appliesTo:['progression',...l],status:'current',lastReviewed:c,reviewedBy:u,version:1,history:[{date:c,change:'Added.'}]},{id:'women-train-same',rule:'Women follow the same core strength principles as men: progressive lifting, full-body, 2+ days a week.',topic:'Training',strength:'moderate',caveat:'This analysis covers young to middle-aged adults. Results for older women can differ when changes are compared in absolute terms.',sources:[{cite:'Roberts et al., 2020',title:'Sex Differences in Resistance Training: A Systematic Review and Meta-Analysis',journal:'Journal of Strength and Conditioning Research',year:2020,url:'https://pubmed.ncbi.nlm.nih.gov/32218059/',kind:'meta-analysis',studied:'women-and-men',finding:'Women and men gained muscle and lower-body strength at similar relative rates on the same programs; women gained relatively more upper-body strength.'}],appliesTo:['plan',...l],status:'current',lastReviewed:c,reviewedBy:u,version:1,history:[{date:c,change:'Added.'}]},{id:'training-frequency',rule:'Plans run 2\u20135 training days a week, with optional walking and easy cardio on other days.',topic:'Training',strength:'strong',caveat:'These are general health guidelines for adults, not a plan for maximum muscle growth.',sources:[{cite:'Bull et al. (WHO), 2020',title:'World Health Organization 2020 guidelines on physical activity and sedentary behaviour',journal:'British Journal of Sports Medicine',year:2020,url:'https://doi.org/10.1136/bjsports-2020-102955',kind:'guideline',studied:'adults',finding:'Adults should do muscle-strengthening activity for all major muscle groups on 2 or more days a week, plus 150\u2013300 minutes of moderate aerobic activity.'}],appliesTo:['schedule','zone2'],status:'current',lastReviewed:c,reviewedBy:u,version:1,history:[{date:c,change:'Added.'}]},{id:'rest-periods',rule:'Big lifts rest about 2\u20133 minutes; small moves rest 45\u201390 seconds. Short sessions cut exercises before they cut rest.',topic:'Training',strength:'moderate',caveat:'Most rest-interval trials studied men. Women are often less fatigable in some tasks, so shorter rest may work for some women on some moves. This is an open question.',sources:[{cite:'Schoenfeld et al., 2016',title:'Longer Interset Rest Periods Enhance Muscle Strength and Hypertrophy in Resistance-Trained Men',journal:'Journal of Strength and Conditioning Research',year:2016,url:'https://pubmed.ncbi.nlm.nih.gov/26605807/',kind:'randomized trial',studied:'men-only',finding:'3-minute rests produced more strength and muscle growth than 1-minute rests in trained men.'},{cite:'Grgic et al., 2017',title:'The effects of short versus long inter-set rest intervals in resistance training on measures of muscle hypertrophy: A systematic review',journal:'European Journal of Sport Science',year:2017,url:'https://doi.org/10.1080/17461391.2017.1340524',kind:'systematic review',studied:'not-checked',finding:'Short and long rests can both build muscle; in trained people, longer rests may have an advantage.'},{cite:'Hunter, 2014',title:'Sex differences in human fatigability: mechanisms and insight to physiological responses',journal:'Acta Physiologica',year:2014,url:'https://pubmed.ncbi.nlm.nih.gov/24433272/',kind:'narrative review',studied:'women-and-men',finding:'Women are usually less fatigable than men in similar-intensity isometric tasks, but the difference depends on the task.'}],appliesTo:['rest-timer','session-length'],status:'current',lastReviewed:c,reviewedBy:u,version:1,history:[{date:c,change:'Added.'}]},{id:'rep-ranges',rule:'Muscle can be built with lighter or heavier weights; the app uses moderate reps (8\u201315) and progresses load for strength.',topic:'Training',strength:'moderate',caveat:'Light loads only build similar muscle when sets are taken close to failure. Heavier loads are better for maximal strength.',sources:[{cite:'Schoenfeld et al., 2017',title:'Strength and Hypertrophy Adaptations Between Low- vs. High-Load Resistance Training: A Systematic Review and Meta-analysis',journal:'Journal of Strength and Conditioning Research',year:2017,url:'https://pubmed.ncbi.nlm.nih.gov/28834797/',kind:'meta-analysis',studied:'not-checked',finding:'Muscle growth was similar with low and high loads; max strength gains favored high loads.'}],appliesTo:['plan',...l],status:'current',lastReviewed:c,reviewedBy:u,version:1,history:[{date:c,change:'Added.'}]},{id:'glute-exercises',rule:'Glute days use hip thrusts and squats/lunges for overall glute size, plus abduction work for the side (upper) glutes.',topic:'Sculpting',strength:'limited',caveat:'The hip thrust vs squat trial was in untrained young adults over 9 weeks. Muscle-activation (EMG) studies show which moves light up a muscle, which does not always predict growth.',sources:[{cite:'Plotkin et al., 2023',title:'Hip thrust and back squat training elicit similar gluteus muscle hypertrophy and transfer similarly to the deadlift',journal:'Frontiers in Physiology',year:2023,url:'https://doi.org/10.3389/fphys.2023.1279170',kind:'randomized trial',studied:'not-checked',finding:'Hip thrusts and squats grew the glutes by similar amounts; squats also grew the thighs more.'},{cite:'Distefano et al., 2009',title:'Gluteal muscle activation during common therapeutic exercises',journal:'Journal of Orthopaedic & Sports Physical Therapy',year:2009,url:'https://pubmed.ncbi.nlm.nih.gov/19574661/',kind:'lab study',studied:'not-checked',finding:'Side-lying hip abduction produced the highest gluteus medius activation of the exercises tested.'}],appliesTo:['hip_thrust','glute_bridge','squat','leg_press','split_squat','reverse_lunge','lunge','step_up','abduction','banded_walk','kickback','curtsy','sculpt'],status:'current',lastReviewed:c,reviewedBy:u,version:1,history:[{date:c,change:'Added.'}]},{id:'spot-reduction',rule:'Sculpting builds muscle where you choose, but the app never promises fat loss from one spot.',topic:'Sculpting',strength:'limited',caveat:'The best-known trial is small (24 people, 6 weeks). Other studies point the same way, but more research in women would help.',sources:[{cite:'Vispute et al., 2011',title:'The Effect of Abdominal Exercise on Abdominal Fat',journal:'Journal of Strength and Conditioning Research',year:2011,url:'https://doi.org/10.1519/JSC.0b013e3181fb4a46',kind:'randomized trial',studied:'women-and-men',finding:'6 weeks of ab exercises alone did not reduce belly fat or waist size, though ab endurance improved.'}],appliesTo:['sculpt','crunch','dead_bug','plank','side_plank','pallof'],status:'current',lastReviewed:c,reviewedBy:u,version:1,history:[{date:c,change:'Added.'}]},{id:'cycle-sync',rule:'Cycle sync learns from your own check-ins and suggests changes. It never automatically cuts your training by cycle phase.',topic:'Cycle',strength:'moderate',caveat:'The research quality on cycle phase and performance is rated low, and individual women vary a lot. That is exactly why the app personalizes instead of prescribing.',sources:[{cite:'McNulty et al., 2020',title:'The Effects of Menstrual Cycle Phase on Exercise Performance in Eumenorrheic Women: A Systematic Review and Meta-Analysis',journal:'Sports Medicine',year:2020,url:'https://doi.org/10.1007/s40279-020-01319-3',kind:'meta-analysis',studied:'women',finding:'Performance might be trivially lower in the early follicular phase; the authors recommend a personalized approach based on each woman\u2019s response.'},{cite:'Colenso-Semple et al., 2023',title:'Current evidence shows no influence of women\u2019s menstrual cycle phase on acute strength performance or adaptations to resistance exercise training',journal:'Frontiers in Sports and Active Living',year:2023,url:'https://doi.org/10.3389/fspor.2023.1054542',kind:'umbrella review',studied:'women',finding:'It is premature to conclude that cycle-phase hormone changes meaningfully affect strength or muscle growth from training.'}],appliesTo:['cycle','checkin'],status:'current',lastReviewed:c,reviewedBy:u,version:1,history:[{date:c,change:'Added.'}]},{id:'cardio-type',rule:'Cardio days use steady, easy cardio; sprint drills are optional add-ons, not the main fat-loss tool.',topic:'Training',strength:'moderate',caveat:'A widely shared 2019 review that favored HIIT for fat loss was retracted; we do not use it.',sources:[{cite:'Steele et al., 2021',title:'Slow and Steady, or Hard and Fast? A Systematic Review and Meta-Analysis of Studies Comparing Body Composition Changes between Interval Training and Moderate Intensity Continuous Training',journal:'Sports',year:2021,url:'https://doi.org/10.3390/sports9110155',kind:'meta-analysis',studied:'adults',finding:'Interval training and steady moderate cardio produced practically the same fat loss.'}],appliesTo:['zone2','hill_sprint','shuttle','climbers','shadowbox'],status:'current',lastReviewed:c,reviewedBy:u,version:1,history:[{date:c,change:'Added.'}]},{id:'injury-prevention',rule:'Every session has a warm-up and strength work for the whole body. Cool-down stretches are for comfort.',topic:'Safety',strength:'moderate',caveat:'Stretching did not reduce injuries in this analysis, so we do not claim our cool-down prevents injury. Sport drills are low-volume and placed early, before fatigue.',sources:[{cite:'Lauersen et al., 2014',title:'The effectiveness of exercise interventions to prevent sports injuries: a systematic review and meta-analysis of randomised controlled trials',journal:'British Journal of Sports Medicine',year:2014,url:'https://pubmed.ncbi.nlm.nih.gov/24100287/',kind:'meta-analysis',studied:'women-and-men',finding:'Strength training reduced sports injuries to less than a third; stretching did not prevent injuries.'}],appliesTo:['warmup','cooldown','a_skip','hill_sprint','superman','flutter','squat_jump','lateral_bound','hollow','bear_crawl','balance_reach','curtsy','shuffle','chop','skater','shuttle','shadowbox','climbers','dead_hang','carry'],status:'current',lastReviewed:c,reviewedBy:u,version:1,history:[{date:c,change:'Added.'}]},{id:'protein-target',rule:'Your protein target is about 1.6 g per kg of body weight per day (capped between 90 and 180 g).',topic:'Nutrition',strength:'moderate',caveat:'The cap and floor are our practical limits. Needs vary with age, training and health; ask a dietitian if you have kidney disease or other conditions.',sources:[{cite:'Morton et al., 2018',title:'A systematic review, meta-analysis and meta-regression of the effect of protein supplementation on resistance training-induced gains in muscle mass and strength in healthy adults',journal:'British Journal of Sports Medicine',year:2018,url:'https://doi.org/10.1136/bjsports-2017-097608',kind:'meta-analysis',studied:'adults',finding:'Across 49 trials, gains in lean mass plateaued at around 1.6 g/kg/day of total protein.'}],appliesTo:['fuel-protein'],status:'current',lastReviewed:c,reviewedBy:u,version:1,history:[{date:c,change:'Added.'}]},{id:'calorie-estimate',rule:'Calories are estimated with the Mifflin-St Jeor equation, adjusted for training days and your goal.',topic:'Nutrition',strength:'strong',caveat:'Any equation can be off by 10% or more for an individual. Treat the number as a starting point and adjust based on how you feel and your progress.',sources:[{cite:'Frankenfield et al., 2005',title:'Comparison of Predictive Equations for Resting Metabolic Rate in Healthy Nonobese and Obese Adults: A Systematic Review',journal:'Journal of the American Dietetic Association',year:2005,url:'https://doi.org/10.1016/j.jada.2005.02.005',kind:'systematic review',studied:'adults',finding:'Mifflin-St Jeor was the most reliable equation, predicting resting metabolism within 10% for more people than the others, but errors exist for individuals.'}],appliesTo:['fuel-calories'],status:'current',lastReviewed:c,reviewedBy:u,version:1,history:[{date:c,change:'Added.'}]},{id:'no-extreme-deficits',rule:'Fat-loss targets are gentle (at most ~15% below maintenance) and never go below 1,400 calories a day in the app.',topic:'Safety',strength:'consensus',caveat:'The 1,400-calorie floor is our safety choice; it does not come from this paper. The consensus statement explains why under-fueling while training harms health.',sources:[{cite:'Mountjoy et al. (IOC), 2023',title:'2023 International Olympic Committee\u2019s (IOC) consensus statement on Relative Energy Deficiency in Sport (REDs)',journal:'British Journal of Sports Medicine',year:2023,url:'https://pubmed.ncbi.nlm.nih.gov/37752011/',kind:'consensus statement',studied:'women-and-men',finding:'Eating too little for the amount of exercise you do (low energy availability) harms many body systems, including hormones, bone and mental health.'}],appliesTo:['fuel-calories','fuel-floor'],status:'current',lastReviewed:c,reviewedBy:u,version:1,history:[{date:c,change:'Added.'}]},{id:'creatine',rule:'The shop lists creatine monohydrate at 3\u20135 g a day, certified products only, with a "check with your doctor" note.',topic:'Supplements',strength:'moderate',caveat:'Research in women is growing but still smaller than in men. Pregnancy and kidney conditions need a doctor\u2019s input.',sources:[{cite:'Kreider et al. (ISSN), 2017',title:'International Society of Sports Nutrition position stand: safety and efficacy of creatine supplementation in exercise, sport, and medicine',journal:'Journal of the International Society of Sports Nutrition',year:2017,url:'https://doi.org/10.1186/s12970-017-0173-z',kind:'position stand',studied:'adults',finding:'Creatine is safe and well tolerated in healthy people in the studied doses, and can improve high-intensity performance and training adaptations.'},{cite:'Smith-Ryan et al., 2021',title:'Creatine Supplementation in Women\u2019s Health: A Lifespan Perspective',journal:'Nutrients',year:2021,url:'https://doi.org/10.3390/nu13030877',kind:'narrative review',studied:'women',finding:'Creatine appears effective for strength and exercise performance in pre-menopausal women; women have lower natural creatine stores.'}],appliesTo:['shop-creatine'],status:'current',lastReviewed:c,reviewedBy:u,version:1,history:[{date:c,change:'Added.'}]}],p={strong:'Strong evidence',moderate:'Moderate evidence',limited:'Limited evidence',consensus:'Expert consensus'},y={women:'Studied in women','women-and-men':'Women and men','men-only':'Men only',adults:'Adults (general)','not-checked':'Participants not yet verified'}},817,[]);